                style={{
                  fontSize: "16px",
                  lineHeight: "28px",
                  marginBottom: i < BOLDTEQ_POINTS.length - 1 ? "8px" : 0,
                }}
              >
                <span
                  style={{ color: "#019ae6", fontWeight: 700, marginRight: "6px" }}
                >
                  ✔
                </span>
                <strong className="text-[#082753]">{point.label}</strong>
                <br />
                {point.detail}
              </p>
            ))}
          </div>

          {/* Boldteq chat bubbles — stacked */}
          <div style={{ marginTop: "30px", display: "flex", flexDirection: "column", gap: "12px" }}>
            {/* Client message */}
            <div style={{ display: "flex", alignItems: "flex-end", gap: "8px" }}>
              <Image
                src="/images/webflow/f8f0feb98079a1670f1d01ab1aa9fadccc312da5.png"
